// Labels: what is printed on a parcel, and how it is fixed to it.
import { record, balance as total } from "./docket.js";
import { docket as book } from "./books.js";

export const LABEL_SIZES = {
  small: [40, 20],
  large: [100, 60],
};
const blank = { id: 0, text: "", size: "small" };
export const sample = bolt(blank);

function pad(text, width) {
  return text.length >= width ? text : text + " ".repeat(width - text.length);
}

export function bolt(parcel) {
  record(parcel.id, "closed");
  return { ...parcel, closed: true, line: pad(parcel.text, 12) };
}

export function boltAll(parcels) {
  return parcels.map((each) => bolt(each));
}

export function unbolt(parcel) {
  book.strike(parcel.id);
  return { ...parcel, closed: false };
}

export function stamp(bolt, date) {
  return `${bolt.id} ${date.toISOString().slice(0, 10)} ${total()}`;
}
